// Sample messages, standing in for the Gmail/IMAP ingestion node.
//
// Two kinds of mail arrive in the same inbox, which is the whole point:
//   - placement postings (job alerts, placement-cell drives)
//   - academic notices (exams, quizzes, submissions, venue changes, registrations)
// plus one piece of noise. The classifier further down has to separate them.
//
// Academic dates are generated RELATIVE TO TODAY (India time), so this demo
// still shows sensible "days left" and reminders whenever it is run - on
// submission day, at the mentor review, or during the 24-hour build.

const TZ = 'Asia/Kolkata';
const at = (n) => new Date(Date.now() + n * 86400000);
const iso = (n) => at(n).toLocaleDateString('en-CA', { timeZone: TZ });          // 2026-10-14
const text = (n) => at(n).toLocaleDateString('en-GB', {                           // 14 Oct 2026
  timeZone: TZ, day: 'numeric', month: 'short', year: 'numeric' });

const placement = [
  {
    source: 'internshala',
    sender: 'alerts@internshala.com',
    subject: 'Software Engineering Intern at Acme Systems',
    received: '2026-10-01',
    body: 'Acme Systems is hiring Software Engineering Interns. Eligibility: B.Tech CSE/IT, 2030 batch, minimum CGPA 8.0, no active backlogs. Apply by 20 Oct 2026.'
  },
  {
    source: 'unstop',
    sender: 'noreply@unstop.com',
    subject: 'Software Engineering Intern at Acme Systems',
    received: '2026-10-01',
    body: 'Acme Systems — Software Engineering Intern. CGPA 8.0 and above, CSE and IT branches, batch of 2030. Deadline 20 October 2026.'
  },
  {
    source: 'placement-cell',
    sender: 'tpo@college.edu',
    subject: 'Campus drive — Borealis Analytics',
    received: '2026-10-02',
    body: 'Borealis Analytics campus drive. Open to all engineering branches, 2030 batch, minimum CGPA 7.0, up to 1 active backlog permitted. Register by 18 Oct 2026.'
  },
  {
    source: 'linkedin',
    sender: 'jobs-noreply@linkedin.com',
    subject: 'Data Intern at Castellan Labs',
    received: '2026-10-02',
    body: 'Castellan Labs is hiring Data Interns in Bengaluru. Apply by 25 Oct 2026.'
  }
];

const academic = [
  // Exam: official notice, plus a group-chat message that gets the date wrong
  { source: 'exam-cell', sender: 'examcell@college.edu', received: iso(-3),
    subject: 'CM-I mid-semester examination schedule',
    body: `Computational Mathematics-I (CM-I) mid-semester exam on ${text(12)} at 9:30 AM, venue AB-5 Room 301.` },
  { source: 'class-group', sender: 'whatsapp-forward', received: iso(-1),
    subject: 'cm1 midsem date??',
    body: `guys CM-I mid sem is on ${text(11)} I think, same room` },

  // Quiz: original notice, then a later venue change
  { source: 'faculty', sender: 'fee.faculty@college.edu', received: iso(-4),
    subject: 'FEE quiz 2 announcement',
    body: `FEE quiz 2 on ${text(5)} at 2:00 PM in AB-5 Room 204.` },
  { source: 'exam-cell', sender: 'examcell@college.edu', received: iso(-1),
    subject: 'Venue change — FEE quiz 2',
    body: `FEE quiz 2 venue changed from AB-5 Room 204 to AB-5 Room 110. Date unchanged: ${text(5)} at 2:00 PM.` },

  // Submission
  { source: 'faculty', sender: 'pps.lab@college.edu', received: iso(-2),
    subject: 'PPS lab record submission',
    body: `Submit the PPS lab record (experiments 1–6) by ${text(3)}, 5:00 PM, in the lab.` },

  // Two equally official sources disagree, on the same day -> a human must decide
  { source: 'faculty', sender: 'emsb.faculty@college.edu', received: iso(-1),
    subject: 'EMSB assignment 3',
    body: `Submit EMSB assignment 3 by ${text(7)}, 11:59 PM, on the LMS.` },
  { source: 'department', sender: 'cse.office@college.edu', received: iso(-1),
    subject: 'Reminder: EMSB assignment 3',
    body: `EMSB assignment 3 is due ${text(8)}, 11:59 PM.` },

  // Event registration
  { source: 'club', sender: 'ieee@college.edu', received: iso(-1),
    subject: 'IEEE workshop registration',
    body: `Registrations for the IEEE ML workshop close on ${text(2)} at 11:59 PM. Workshop on ${text(9)}.` }
];

const noise = [
  { source: 'hostel', sender: 'mess@college.edu', received: iso(0),
    subject: 'Mess menu for this week',
    body: 'This week\'s mess menu is attached. Sunday special: paneer butter masala.' }
];

return [...placement, ...academic, ...noise].map(p => ({ json: p }));

// Deterministic deduplication.
//
// Why code and not the model: "have I seen this before?" is an exact-match
// question. Hashing is reproducible, costs nothing, and can be explained to a
// judge in one sentence. An LLM asked the same question gives a different
// answer on a different day.
//
// The key is subject + received date, NOT the sender: the same opening arrives
// from different senders (Internshala, Unstop), and those must collapse into one.
//
// The hash is cyrb53, a small pure-JavaScript hash, instead of require('crypto').
// n8n blocks Node's built-in modules in Code nodes unless the server is started
// with NODE_FUNCTION_ALLOW_BUILTIN=crypto, so this keeps the workflow importable
// on any n8n install with no extra setup. It is not for security, only identity.
const cyrb53 = (str, seed = 0) => {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16).padStart(14, '0');
};

// Normalise before hashing: lowercase, strip punctuation that differs between
// senders, collapse whitespace. Without this the same opening hashes differently.
const normalise = (s) => String(s || '')
  .toLowerCase()
  .replace(/[^a-z0-9 ]/g, '')
  .replace(/\\s+/g, ' ')
  .trim();

const seen = new Set();
const unique = [];
for (const item of $input.all()) {
  const p = item.json;
  const hash = cyrb53(`${normalise(p.subject)}|${normalise(p.received)}`);
  if (seen.has(hash)) continue;      // duplicate: drop it
  seen.add(hash);
  unique.push({ json: { ...p, dedup_hash: hash.slice(0, 12) } });
}
return unique;

// Classify each message: opportunity, deadline, or noise.
//
// In the full build this is the Text Classifier node (with its "other" branch
// switched on, or unmatched items are silently dropped). The stub uses keyword
// rules so the routing can be tested before the AI exists.
//
// ORDER MATTERS: placement postings also contain words like "deadline" and
// "register by", so they are checked first. A posting is never a deadline item.
// Every item carries the rule that classified it, so a wrong route is easy to trace.

const RULES = [
  { type: 'opportunity', re: /\b(hiring|interns?|internship|campus drive|cgpa)\b/i },
  { type: 'deadline',    re: /(\bexam|mid ?-?sem|\bquiz|submi|\bdue\b|deadline|registr|venue)/i }
];

return $input.all().map(item => {
  const text = `${item.json.subject} ${item.json.body}`;
  const hit = RULES.find(r => r.re.test(text));
  return {
    json: {
      ...item.json,
      type: hit ? hit.type : 'noise',
      type_reason: hit ? `matched "${text.match(hit.re)[0]}"` : 'no rule matched'
    }
  };
});

// Field extraction, stubbed with regular expressions.
//
// In the full build this node is replaced by the Information Extractor, which
// returns the same schema from unstructured text. The schema is fixed here so
// that everything downstream can be written and tested before the AI exists —
// and so that a failure in the model layer cannot change the shape of the data.
//
// Rule that matters: a field not stated in the source must be null, never a
// guess. Downstream code treats null as "unknown", not as "no requirement".
return $input.all().map(item => {
  const text = item.json.body || '';

  const num = (re) => {
    const m = text.match(re);
    return m ? Number(m[1]) : null;
  };

  const branches = /all engineering branches|all branches/i.test(text)
    ? ['ALL']
    : (text.match(/\b(CSE|IT|ECE|EEE|MECH|CIVIL)\b/gi) || []).map(b => b.toUpperCase());

  return {
    json: {
      ...item.json,
      extracted: {
        company:          (text.match(/^([A-Z][\w& ]+?)(?: is hiring| campus drive| —)/) || [])[1] || null,
        cgpa_min:         num(/(?:CGPA|cgpa)\s*(?:of\s*)?([0-9]\.[0-9])/),
        batch_year:       num(/batch(?: of)?\s*(20\d\d)/i) || num(/(20\d\d)\s*batch/i),
        backlogs_allowed: /no active backlog/i.test(text) ? 0 : num(/up to (\d+) active backlog/i),
        branches:         branches.length ? branches : null,
        deadline_text:    (text.match(/(?:Apply by|Deadline|Register by)\s*([^.]+)/i) || [])[1] || null
      }
    }
  };
});

// The eligibility decision — the heart of the project.
//
// Three outcomes, never two: eligible, not_eligible, or ambiguous. "Ambiguous"
// exists because a missing criterion is not the same as a satisfied one; those
// items go to a human instead of being silently passed or failed.
//
// Every outcome carries a reason string. The reason is what gets written to the
// decision log and shown in the digest, and it is why this system can be audited
// while a prompt-based judgement cannot.

const profile = {            // in the full build this is read from Google Sheets
  name: 'Pulkit',
  cgpa: 7.6,
  branch: 'CSE',
  batch_year: 2030,
  active_backlogs: 0
};

return $input.all().map(item => {
  const e = item.json.extracted || {};
  const reasons = [];
  const unknowns = [];

  // CGPA
  if (e.cgpa_min === null)            unknowns.push('CGPA cutoff not stated');
  else if (profile.cgpa < e.cgpa_min) reasons.push(`needs ${e.cgpa_min.toFixed(1)} CGPA, profile has ${profile.cgpa}`);

  // Branch — 'ALL' is an explicit wildcard, absence is not
  if (!e.branches)                                                   unknowns.push('branches not stated');
  else if (!e.branches.includes('ALL') && !e.branches.includes(profile.branch))
                                                                      reasons.push(`open to ${e.branches.join('/')}, profile is ${profile.branch}`);

  // Batch year
  if (e.batch_year === null)                    unknowns.push('batch year not stated');
  else if (e.batch_year !== profile.batch_year) reasons.push(`for the ${e.batch_year} batch, profile is ${profile.batch_year}`);

  // Backlogs
  if (e.backlogs_allowed === null)                              unknowns.push('backlog rule not stated');
  else if (profile.active_backlogs > e.backlogs_allowed)        reasons.push(`allows ${e.backlogs_allowed} backlogs, profile has ${profile.active_backlogs}`);

  let verdict, reason;
  if (reasons.length) {
    verdict = 'not_eligible';
    reason  = reasons.join('; ');
  } else if (unknowns.length) {
    verdict = 'ambiguous';
    reason  = `human check needed: ${unknowns.join('; ')}`;
  } else {
    verdict = 'eligible';
    reason  = 'meets every stated criterion';
  }

  return {
    json: {
      company:  e.company,
      source:   item.json.source,
      hash:     item.json.dedup_hash,
      verdict,
      reason,
      deadline: e.deadline_text,
      decided_at: new Date().toISOString()
    }
  };
});

// Extract the date facts from an academic notice.
//
// In the full build this is a second Information Extractor (same Gemini model,
// different schema). As with placement, the rule is: a field that is not stated
// is null, never a guess.
//
// Dates are turned into ISO strings by hand (YYYY-MM-DD) instead of new Date(text),
// because new Date() parses in the server's timezone and can shift a date by a day.

const MONTHS = { jan:1, feb:2, mar:3, apr:4, may:5, jun:6, jul:7, aug:8, sep:9, oct:10, nov:11, dec:12 };
const toIso = (s) => {
  const m = s && s.match(/(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})/);
  if (!m) return null;
  return `${m[3]}-${String(MONTHS[m[2].toLowerCase()]).padStart(2, '0')}-${m[1].padStart(2, '0')}`;
};

// How much each source is trusted when two of them disagree.
const AUTHORITY = { 'exam-cell': 3, 'faculty': 3, 'department': 3, 'club': 2, 'class-group': 1 };

return $input.all().map(item => {
  const t = item.json.body || '';

  const course = (t.match(/\b(CM-I|FEE|PPS|EMSB|IEEE)\b/) || [])[1] || null;
  const kind =
      /registr/i.test(t)                         ? 'registration'
    : /submi|\bdue\b|assignment/i.test(t)        ? 'submission'
    : /\bquiz/i.test(t)                          ? 'quiz'
    : /\bexam|mid ?-?sem/i.test(t)               ? 'exam'
    : null;

  const venues = t.match(/AB-\d+ Room \d+/g) || [];   // "changed from X to Y" -> the last one wins

  return {
    json: {
      ...item.json,
      extracted: {
        course,
        kind,
        date:   toIso((t.match(/\d{1,2} [A-Z][a-z]{2,8} \d{4}/) || [])[0]),  // first date = the deadline
        time:   (t.match(/\d{1,2}:\d{2}\s?(?:AM|PM)/i) || [])[0] || null,
        venue:  venues.length ? venues[venues.length - 1] : null,
        authority: AUTHORITY[item.json.source] ?? 1
      }
    }
  };
});

// Resolve conflicts between notices about the same thing.
//
// Hash dedup only catches exact repeats. Here, different messages about the SAME
// event (same course + kind) are grouped, and one answer is chosen in code:
//
//   1. Higher authority wins. The exam cell beats a class-group forward.
//   2. Same authority, later message wins, and the change is recorded
//      ("venue changed: Room 204 -> Room 110").
//   3. Same authority, same day, different dates -> nobody can tell which is
//      right, so the item is marked needs_human. The system says what it doesn't know.

const groups = {};
for (const item of $input.all()) {
  const e = item.json.extracted;
  const key = `${e.course}|${e.kind}`;
  (groups[key] = groups[key] || []).push({ ...e, source: item.json.source, received: item.json.received });
}

const out = [];
for (const notices of Object.values(groups)) {
  notices.sort((a, b) => b.authority - a.authority || b.received.localeCompare(a.received));
  const top = notices[0];
  const notes = [];
  let status = 'confirmed';

  for (const n of notices.slice(1)) {
    const sameRank = n.authority === top.authority;
    if (sameRank && n.received === top.received && n.date !== top.date) {
      status = 'needs_human';
      notes.push(`${top.source} says ${top.date}, ${n.source} says ${n.date}, both sent ${n.received}`);
    } else if (sameRank) {
      if (n.venue && top.venue && n.venue !== top.venue) notes.push(`venue changed: ${n.venue} → ${top.venue} (later notice)`);
      if (n.date && top.date && n.date !== top.date)    notes.push(`date changed: ${n.date} → ${top.date} (later notice)`);
      if (n.time && top.time && n.time !== top.time)    notes.push(`time changed: ${n.time} → ${top.time} (later notice)`);
    } else if (n.date && n.date !== top.date) {
      notes.push(`${n.source} says ${n.date}; ignored, ${top.source} is the authority`);
    }
  }

  out.push({ json: {
    course: top.course, kind: top.kind, date: top.date, time: top.time, venue: top.venue,
    source: top.source, status, notes, notices: notices.length
  }});
}
return out;

// Plan the schedule: days left, reminder dates, and the action to take.
//
// Everything is computed in India time. "Today" comes from the clock, so the
// same workflow gives the right answer on any day it runs.
//
// Reminder offsets depend on the kind of item: an exam deserves a week's
// warning, a registration only a day. Reminders already in the past are dropped.

const TZ = 'Asia/Kolkata';
const today = new Date().toLocaleDateString('en-CA', { timeZone: TZ });          // YYYY-MM-DD
const dayNum = (iso) => Date.UTC(...iso.split('-').map((v, i) => i === 1 ? v - 1 : +v)) / 86400000;
const shift = (iso, n) => new Date((dayNum(iso) + n) * 86400000).toISOString().slice(0, 10);

const OFFSETS = { exam: [7, 3, 1], quiz: [2, 1], submission: [2, 1], registration: [1, 0] };

return $input.all().map(item => {
  const d = item.json;
  let days_left = null, reminders = [], action, status = d.status;

  if (!d.date) {
    status = 'needs_human';
    action = 'ask a human: no date found in the notice';
  } else {
    days_left = dayNum(d.date) - dayNum(today);
    if (days_left < 0) {
      status = 'passed';
      action = 'nothing to schedule: date has passed';
    } else if (status === 'needs_human') {
      days_left = null;                  // the date itself is disputed, so no countdown
      action = 'ask a human on Telegram before adding anything to the calendar';
    } else {
      reminders = (OFFSETS[d.kind] || [1])
        .map(n => shift(d.date, -n))
        .filter(r => r >= today);
      action = `calendar event + ${reminders.length} reminder(s)`;
    }
  }

  return { json: {
    item: `${d.course} ${d.kind}`,
    when: status === 'needs_human' ? 'disputed, see why' : [d.date, d.time].filter(Boolean).join(' '),
    venue: d.venue,
    days_left,
    status,
    action,
    reminders: reminders.join(', '),
    why: d.notes.length ? d.notes.join('; ') : `single notice from ${d.source}`
  }};
});
